function subwayText(
    game: GameRuntime,
    fr: string,
    en: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    let out = lang === 'en' ? en : fr;
    for (const [k, v] of Object.entries(vars)) {
        out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return out;
}

function emptySubwayState(): SubwayState {
    return {
        isActive: false,
        currentBattle: 0,
        winsThisRun: 0,
        currentEnemyIndex: 0,
        enemyTeam: [],
        trainerName: '',
        trainerSpriteKey: 'youngster',
        wagonIndex: 0,
        bestStreakThisRun: 0,
        dailySetId: '',
    };
}

function notifySubwayUiChanged(game: GameRuntime): void {
    notifyTowerChanged(game);
    const run = () => notifyShopChanged(game);
    const delay = getShopRefreshDelayMs();
    if (delay > 0) window.setTimeout(run, delay);
    else run();
}

export function reconcileSubwayWeeklyProgress(game: GameRuntime): boolean {
    if (!ensureSubwayWeeklyProgress(game)) return false;
    toast.info(
        subwayText(game, 'Battle Subway', 'Battle Subway'),
        subwayText(
            game,
            'Nouvelle semaine : progression des wagons réinitialisée.',
            'New week: wagon progression has been reset.',
        ),
    );
    logMessage(subwayText(
        game,
        'Battle Subway — nouvelle semaine : les wagons repartent au niveau 1.',
        'Battle Subway — new week: wagons reset to level 1.',
    ));
    notifySubwayUiChanged(game);
    return true;
}

export function isSubwayIntroQuestActive(game: GameRuntime): boolean {
    return !!(game.quests && game.quests.some(
        (q) => q.id === 'story_unova_battle_subway' && q.accepted && !q.completed,
    ));
}

function resetActiveSubwayQuestProgress(game: GameRuntime): void {
    for (const q of game.quests ?? []) {
        if (!q.accepted || q.completed) continue;
        if (q.trackingKey !== 'subway_battles_won') continue;
        q.current = 0;
        q.updateProgress?.(0);
    }
}

export function canAffordSubwayRunTickets(game: GameRuntime): boolean {
    if (isSubwayIntroQuestActive(game)) return true;
    return canAffordCombatEntryTicket(game);
}

function canStartSubwayRun(game: GameRuntime): string | null {
    if (!game.unlockedFeatures?.subwayTab) {
        return subwayText(game, 'Le Battle Subway n\'est pas encore débloqué.', 'Battle Subway is not unlocked yet.');
    }
    if (game.subwayState?.isActive) {
        return subwayText(game, 'Une run Subway est déjà en cours !', 'A Subway run is already in progress!');
    }
    if (game.towerState?.isActive) {
        return subwayText(game, 'Terminez d\'abord la Tour de Combat.', 'Finish the Battle Tower first.');
    }
    const arenaActive = !!(game.arenaState && game.arenaState.active);
    const gymTrainerActive = !!(game.gymTrainerState && game.gymTrainerState.active);
    const trainerCombatInProgress = game.combatState === 'fighting' || game.combatState === 'starting';
    if ((arenaActive || gymTrainerActive) && (trainerCombatInProgress || game.currentEnemy)) {
        return subwayText(game, 'Terminez le combat de dresseur en cours.', 'Finish the ongoing trainer battle first.');
    }
    const ticketsRequired = isSubwayIntroQuestActive(game) ? 0 : getCombatEntryTicketCost();
    if (ticketsRequired > 0 && !canAffordCombatEntryTicket(game, ticketsRequired)) {
        return subwayText(
            game,
            'Pas assez de Tickets de Combat ({have}/{need}).',
            'Not enough Combat Tickets ({have}/{need}).',
            { have: game.combatTickets ?? 0, need: ticketsRequired },
        );
    }
    return null;
}

function beginSubwayBattle(game: GameRuntime, battleIndex: number): void {
    const { team, trainer } = generateSubwayTrainerTeamLogic(game, battleIndex);
    const lang = game.normalizeLanguage?.(game.language) === 'en' ? 'en' : 'fr';
    game.subwayState.currentBattle = battleIndex;
    game.subwayState.enemyTeam = team;
    game.subwayState.currentEnemyIndex = 0;
    game.subwayState.trainerName = trainer.name[lang] ?? trainer.name.fr;
    game.subwayState.trainerSpriteKey = trainer.spriteKey;
    resetEnemySubwaySwitchCounters(game);

    game.currentEnemy = arrayAt(team, 0) ?? null;
    if (game.currentEnemy) {
        game.currentEnemy._focusSashUsed = false;
        applyHazardEntryTalentOnEnemyEntry(game, game.currentEnemy);
        consumePendingTerrainExtenderStatus(game, game.currentEnemy, (msg) => logMessage(msg));
    }
    game.combatState = 'starting';
    game.combatStartTime = Date.now();
    resetCombatTurnTally(game);
    game.triggerAutoSelect?.();

    logMessage(subwayText(
        game,
        'Combat {n}/7 : {trainer} envoie {pokemon} !',
        'Battle {n}/7: {trainer} sends {pokemon}!',
        {
            n: battleIndex,
            trainer: game.subwayState.trainerName,
            pokemon: game.currentEnemy?.name ?? '???',
        },
    ));
}

export function initSubwayRunState(game: GameRuntime): void {
    healTeamForTowerRun(game);
    Creature.setResonanceGameRef(game);
    game.playerTeam.forEach((c) => c.recalculateStats?.());

    migrateLegacySubwayProgress(game);
    reconcileSubwayWeeklyProgress(game);
    const set = getSubwayDailySet();
    const entry = getSubwaySetProgressEntry(game, set.id);
    const wagonIndex = entry.wagonsCleared + 1;

    game.subwayState = {
        isActive: true,
        currentBattle: 1,
        winsThisRun: 0,
        currentEnemyIndex: 0,
        enemyTeam: [],
        trainerName: '',
        trainerSpriteKey: 'youngster',
        wagonIndex,
        bestStreakThisRun: 0,
        dailySetId: set.id,
    };

    if (game.activeCreatureIndex != null && game.playerTeam[game.activeCreatureIndex]) {
        game.currentPlayerCreature = game.playerTeam[game.activeCreatureIndex] ?? null;
    }
    if (game.currentPlayerCreature) {
        game.currentPlayerCreature._focusSashUsed = false;
    }

    beginSubwayBattle(game, 1);
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifyTowerChanged(game);
}

export function startSubwayRunLogic(game: GameRuntime): void {
    const block = canStartSubwayRun(game);
    if (block) {
        logMessage(block);
        return;
    }

    if (game.arenaState?.active) {
        if (typeof game.resetArenaState === 'function') game.resetArenaState();
        else if (game.arenaState) game.arenaState.active = false;
    }
    if (game.gymTrainerState?.active) game.gymTrainerState = null;

    const ticketsRequired = isSubwayIntroQuestActive(game) ? 0 : getCombatEntryTicketCost();
    if (ticketsRequired > 0 && !tryConsumeCombatEntryTicket(game, ticketsRequired)) {
        return;
    }

    if (typeof game.enterGameContext === 'function') {
        game.enterGameContext('subway');
    }

    logMessage(subwayText(
        game,
        'Le wagon du Battle Subway part ! Stats brutes — pas de résonance.',
        'The Battle Subway wagon departs! Raw stats — no resonance cap.',
    ));

    resetActiveSubwayQuestProgress(game);
    initSubwayRunState(game);
}

export function advanceSubwayAfterTrainerWinLogic(game: GameRuntime): void {
    if (!game.subwayState?.isActive) return;

    game.subwayState.winsThisRun += 1;
    game.subwayState.bestStreakThisRun = Math.max(
        game.subwayState.bestStreakThisRun,
        game.subwayState.winsThisRun,
    );

    if (typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('subway_battles_won');
    }
    trackAcademySubwayWin(game);

    const expGain = Math.floor(15 * (game.getExpMultiplier?.() ?? 1));
    if (expGain > 0) {
        game.playerTeam.forEach((c) => c.gainExp?.(expGain));
    }

    healTeamForTowerRun(game);

    if (game.subwayState.winsThisRun >= SUBWAY_BATTLES_PER_WAGON) {
        endSubwayRunLogic(game, false);
        return;
    }

    const nextBattle = game.subwayState.winsThisRun + 1;
    beginSubwayBattle(game, nextBattle);
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifyTowerChanged(game);
}

export function endSubwayRunLogic(game: GameRuntime, isForfeit: boolean): void {
    if (!game.subwayState?.isActive) return;
    playGameSfx('runEnd');

    const wins = game.subwayState.winsThisRun;
    const perfect = !isForfeit && wins >= SUBWAY_BATTLES_PER_WAGON;
    const setId = game.subwayState.dailySetId || getSubwayDailySet().id;
    migrateLegacySubwayProgress(game);
    const entry = getSubwaySetProgressEntry(game, setId);
    const bp = computeSubwayBpReward(wins, isForfeit);

    if (bp > 0) {
        game.subwayBP = (game.subwayBP ?? 0) + bp;
        toast.success(
            subwayText(game, 'Battle Subway', 'Battle Subway'),
            subwayText(
                game,
                '+{bp} Points Subway ({wins} victoire(s)).',
                '+{bp} Subway Points ({wins} win(s)).',
                { bp, wins },
            ),
        );
        logMessage(subwayText(
            game,
            'Run Subway terminée : {wins}/7 — +{bp} BP.',
            'Subway run over: {wins}/7 — +{bp} BP.',
            { wins, bp },
        ));
    } else if (isForfeit) {
        logMessage(subwayText(game, 'Run Subway abandonnée.', 'Subway run forfeited.'));
    }

    if (perfect) {
        // Wagons never decrease: only a perfect 7/7 increments progress. Failures keep the same wagon.
        entry.wagonsCleared += 1;
        const wagonCleared = Math.max(1, Number(game.subwayState.wagonIndex) || 1);
        entry.bestStreak = Math.max(entry.bestStreak, wagonCleared);
        if (typeof game.checkSpecialQuests === 'function') {
            game.checkSpecialQuests('subway_wagon_validated', { wagonIndex: wagonCleared });
        }
    } else {
        resetActiveSubwayQuestProgress(game);
    }
    ensureSubwaySetProgress(game)[setId] = entry;
    recomputeSubwayGlobalAggregates(game);

    if (typeof game.leaveGameContext === 'function') {
        game.leaveGameContext();
    }

    game.subwayState = emptySubwayState();
    game.combatState = 'waiting';
    game.lastCombatTime = Date.now();
    game.currentEnemy = null;

    game.playerTeam.forEach((c) => {
        (c as CreatureData & { heal?: () => void }).heal?.();
    });

    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifySubwayUiChanged(game);
    game.saveGame?.();
}

export function buySubwayShopItemLogic(game: GameRuntime, itemId: string): boolean {
    const def = SUBWAY_SHOP_ITEMS.find((i) => i.id === itemId);
    if (!def) return false;
    if (!game.subwayShopPurchases) game.subwayShopPurchases = {};

    const bought = Number(game.subwayShopPurchases[itemId] ?? 0);
    const isSoldOut = def.maxPurchases != null && bought >= def.maxPurchases;

    if (isSoldOut) {
        logMessage(subwayText(game, 'Article épuisé.', 'Item sold out.'));
        return false;
    }

    const cost = getSubwayShopItemCost(def);
    if ((game.subwayBP ?? 0) < cost) {
        logMessage(subwayText(game, 'Pas assez de Points Subway.', 'Not enough Subway Points.'));
        return false;
    }

    game.subwayBP -= cost;
    playGameSfx('buy');
    game.subwayShopPurchases[itemId] = bought + 1;
    if (def.grant === 'towerQuickClearTickets') {
        const have = Math.max(0, Math.floor(Number(game.towerQuickClearTickets) || 0));
        game.towerQuickClearTickets = have + def.amount;
    } else {
        game.addItem?.(def.itemKey, def.amount, false);
    }

    const lang = game.normalizeLanguage?.(game.language) === 'en' ? 'en' : 'fr';
    logMessage(subwayText(
        game,
        'Achat Subway : {name} (-{cost} BP).',
        'Subway purchase: {name} (-{cost} BP).',
        { name: def.name[lang], cost },
    ));
    notifySubwayUiChanged(game);
    game.saveGame?.();
    return true;
}

