/**
 * @file championsTowerLogic.ts
 * Pure logic for Paldea Champions Tower gauntlet.
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import {
    CHAMPIONS_TOWER_LEAGUE_COUNT,
    CHAMPIONS_TOWER_LEAGUE_IDS,
    type ChampionsTowerLeagueId,
} from '../../constants/balance/championsTowerLeagues.ts';
import { ARENAS } from '../../constants/balance/arenasTrainers/index.ts';
import { RARITY, TYPES } from '../../constants/core.ts';
import { Creature } from '../../Creature.ts';
import { pickTrainerMoves } from './trainerMovesets.ts';
import {
    resolveEliteFourChampionPower,
    type EliteFourDefLike,
    type GymArenaEntry,
} from './arenaChampionPower.ts';
import type { ChampionsTowerState } from '../types/combat.js';
import type { GameRuntime } from '../types/game.js';
import type { CreatureData } from '../types/creature.js';

export interface EliteFourTrainerDef {
    championName?: string;
    type?: string;
    team?: Array<{ name: string; level: number; moves?: string[] }>;
}

export interface EliteFourDef {
    id?: string;
    name?: string;
    regionId?: string;
    requiredBadge?: string;
    trainers?: EliteFourTrainerDef[];
}

export function getChampionsTowerCycleStatMult(cycle: number): number {
    const cfg = BALANCE.CHAMPIONS_TOWER;
    const c = Math.max(1, Math.floor(cycle) || 1);
    return cfg.CYCLE_STAT_MULT_BASE + (c - 1) * cfg.CYCLE_STAT_MULT_PER_CYCLE;
}

export function getChampionsTowerCycleLevelBonus(cycle: number): number {
    const cfg = BALANCE.CHAMPIONS_TOWER;
    const c = Math.max(1, Math.floor(cycle) || 1);
    return (c - 1) * cfg.CYCLE_LEVEL_BONUS_PER_CYCLE;
}

export function getChampionsTowerLeagueId(leagueIndex: number): ChampionsTowerLeagueId {
    const idx = Math.max(0, Math.min(CHAMPIONS_TOWER_LEAGUE_COUNT - 1, Math.floor(leagueIndex) || 0));
    return CHAMPIONS_TOWER_LEAGUE_IDS[idx] ?? 'elite_four_gen1';
}

export function getEliteFourDefForChampionsTower(
    game: GameRuntime,
    leagueId: string,
): EliteFourDef | null {
    if (typeof game.getEliteFourDefinition === 'function') {
        return game.getEliteFourDefinition(leagueId) as EliteFourDef | null;
    }
    return null;
}

export function buildChampionsTowerTrainerTeam(
    game: GameRuntime,
    leagueId: string,
    trainerIndex: number,
    cycle: number,
): { team: CreatureData[]; trainerName: string; trainerSpriteKey: string } {
    const eliteDef = getEliteFourDefForChampionsTower(game, leagueId);
    const trainers = eliteDef?.trainers ?? [];
    const trainer = trainers[Math.max(0, Math.min(trainers.length - 1, trainerIndex))];
    const trainerName = trainer?.championName ?? 'Champion';
    const trainerSpriteKey = String(trainerName).toLowerCase().replace(/\s+/g, '_');
    const team: CreatureData[] = [];

    if (!trainer) {
        return { team, trainerName, trainerSpriteKey };
    }

    const arenaPowerCfg = BALANCE?.ARENA_POWER ?? null;
    const { teamLevel, championStatMult } = resolveEliteFourChampionPower(
        eliteDef as EliteFourDefLike,
        ARENAS,
        arenaPowerCfg,
    );
    const cycleStatMult = getChampionsTowerCycleStatMult(cycle);
    const levelBonus = getChampionsTowerCycleLevelBonus(cycle);
    const statMult = championStatMult * cycleStatMult;
    const trainerType = trainer.type ?? TYPES.NORMAL;

    for (const entry of trainer.team ?? []) {
        const entryLevel = Number(entry.level);
        const creatureLevel = (Number.isFinite(entryLevel) && entryLevel > 0 ? entryLevel : teamLevel) + levelBonus;
        const creature = new Creature(
            entry.name,
            trainerType,
            creatureLevel,
            RARITY.EPIC,
            true,
            false,
        ) as unknown as CreatureData;
        creature.currentMoves = pickTrainerMoves(entry.name, trainerType, entry.moves ?? null, { ensureTypeDiversity: true });
        creature.maxHp = Math.floor(creature.maxHp * statMult);
        creature.attack = Math.floor(creature.attack * statMult);
        creature.spattack = Math.floor(creature.spattack * statMult);
        creature.defense = Math.floor(creature.defense * statMult);
        creature.spdefense = Math.floor(creature.spdefense * statMult);
        creature.speed = Math.floor(creature.speed * statMult);
        creature.currentHp = creature.maxHp;
        creature.assignRandomTalent?.();
        creature.actionGauge = 0;
        creature.actionThreshold = BALANCE.ATB_ACTION_THRESHOLD;
        team.push(creature);
    }

    return { team, trainerName, trainerSpriteKey };
}

export function emptyChampionsTowerState(): ChampionsTowerState {
    return {
        isActive: false,
        cycle: 1,
        leagueIndex: 0,
        trainerIndex: 0,
        currentEnemyIndex: 0,
        enemyTeam: [],
        leagueId: CHAMPIONS_TOWER_LEAGUE_IDS[0],
        trainerName: '',
        trainerSpriteKey: 'youngster',
    };
}

export function normalizeChampionsTowerState(raw: unknown): ChampionsTowerState {
    const base = emptyChampionsTowerState();
    if (!raw || typeof raw !== 'object') return base;
    const o = raw as Record<string, unknown>;
    return {
        isActive: o.isActive === true,
        cycle: Math.max(1, Math.floor(Number(o.cycle) || 1)),
        leagueIndex: Math.max(0, Math.floor(Number(o.leagueIndex) || 0)),
        trainerIndex: Math.max(0, Math.floor(Number(o.trainerIndex) || 0)),
        currentEnemyIndex: Math.max(0, Math.floor(Number(o.currentEnemyIndex) || 0)),
        enemyTeam: Array.isArray(o.enemyTeam) ? o.enemyTeam as CreatureData[] : [],
        leagueId: typeof o.leagueId === 'string' ? o.leagueId : CHAMPIONS_TOWER_LEAGUE_IDS[0],
        trainerName: typeof o.trainerName === 'string' ? o.trainerName : '',
        trainerSpriteKey: typeof o.trainerSpriteKey === 'string' ? o.trainerSpriteKey : 'youngster',
        runStats: o.runStats && typeof o.runStats === 'object'
            ? o.runStats as ChampionsTowerState['runStats']
            : undefined,
    };
}

export function isLastTrainerInLeague(game: GameRuntime, state: ChampionsTowerState): boolean {
    const eliteDef = getEliteFourDefForChampionsTower(game, state.leagueId);
    const trainers = eliteDef?.trainers ?? [];
    return state.trainerIndex >= trainers.length - 1;
}

export function isLastLeagueInCycle(state: ChampionsTowerState): boolean {
    return state.leagueIndex >= CHAMPIONS_TOWER_LEAGUE_COUNT - 1;
}

export function shouldHealBetweenLeagues(): boolean {
    return Boolean(BALANCE.CHAMPIONS_TOWER.HEAL_BETWEEN_LEAGUES);
}

export function shouldHealBetweenTrainers(): boolean {
    return Boolean(BALANCE.CHAMPIONS_TOWER.HEAL_BETWEEN_TRAINERS);
}
