function towerT(
  game: GameRuntime,
  key: string,
  fallback: string,
  vars?: Record<string, string | number>,
): string {
  let out: string;
  if (typeof game.t === 'function') {
    const translated = vars ? game.t(key, vars) : game.t(key);
    out = translated && translated !== key ? translated : fallback;
  } else {
    out = fallback;
  }
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return out;
}

/** Deferred placeholder templates — game.t strips unknown {vars} unless preserved. */
function towerTemplate(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t !== 'function') return fallback;

  const placeholderKeys = [...fallback.matchAll(/\{(\w+)\}/g)].map((m) => m[1]);
  const preserveVars: Record<string, string> = {};
  for (const k of placeholderKeys) {
    if (!k) continue;
    preserveVars[k] = `{${k}}`;
  }

  const got = game.t(key, preserveVars);
  return got && got !== key ? got : fallback;
}

function _buildTowerStartLabelHtml(game: GameRuntime): string {
  const batchSize = clampTowerBatchSize(game);
  const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
  const ticketWord = ticketsRequired === 1
    ? towerT(game, 'tower.startTicketSingular', 'ticket')
    : towerT(game, 'tower.startTicketPlural', 'tickets');
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  if (batchSize > 1) {
    const perRunHint = towerT(game, 'tower.batch.perRunTicketHint', 'requis (1/run)');
    return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${ticketsRequired} ${ticketImg} ${ticketWord} ${perRunHint} (${batchSize} ${towerT(game, 'tower.batch.runsShort', 'runs')})`;
  }
  if (ticketsRequired === 0) {
    return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${towerT(game, 'tower.startFreeQuest', 'gratuit (quete)')}`;
  }
  return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${ticketsRequired} ${ticketImg} ${towerT(game, 'tower.startRequirement', 'requis')}`;
}

function isTowerStartDisabled(game: GameRuntime): boolean {
    const batchSize = clampTowerBatchSize(game);
    const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
    if (game.championsTowerState?.isActive) return true;
    if (isTowerClimbQuestActive(game) && batchSize === 1) return false;
    return (game.combatTickets ?? 0) < ticketsRequired;
}

function buildSubwayStartLabelHtml(game: GameRuntime): string {
  const ticketsRequired = isSubwayIntroQuestActive(game) ? 0 : getCombatEntryTicketCost();
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  if (ticketsRequired === 0) {
    return `${towerT(game, 'subway.startLabel', 'Lancer un wagon')} - ${towerT(game, 'subway.startFreeQuest', 'gratuit (quête)')}`;
  }
  return `${towerT(game, 'subway.startLabel', 'Lancer un wagon')} - ${ticketsRequired} ${ticketImg}`;
}

function isSubwayStartDisabled(game: GameRuntime): boolean {
  if (game.subwayState?.isActive || game.towerState?.isActive || game.championsTowerState?.isActive) return true;
  return !canAffordSubwayRunTickets(game);
}


interface SubwayStartData {
  mainLabel: string;
  subLabel: string;
  shortfallLabel: string | null;
  fillRatio: number;
  state: 'buyable' | 'short';
}

function computeSubwayStartData(game: GameRuntime, currentWagon: number, language: string): SubwayStartData {
  const ticketsRequired = isSubwayIntroQuestActive(game) ? 0 : getCombatEntryTicketCost();
  const combatTickets = Math.max(0, Math.floor(Number(game.combatTickets) || 0));
  const isFree = ticketsRequired === 0;
  const isShort = !isFree && combatTickets < ticketsRequired;
  const state: 'buyable' | 'short' = isShort ? 'short' : 'buyable';
  const fillRatio = ticketsRequired > 0 ? Math.min(1, Math.max(0, combatTickets / ticketsRequired)) : 1;
  const lvlOffset = getSubwayWagonLevelOffset(currentWagon);
  const statPct = Math.round((getSubwayWagonStatMult(currentWagon) - 1) * 100);
  const mainLabel = towerT(game, 'subway.startLabel', 'Lancer un wagon');

  const isEn = language === 'en';
  const ticketWord = ticketsRequired === 1 ? 'ticket' : 'tickets';
  const dispoWord = isEn ? 'avail.' : 'dispo';
  const rewardPart = isEn ? '+1 BP if clear' : '+1 BP si complet';

  let costPart = '';
  if (isFree) {
    costPart = isEn ? 'Free (quest)' : 'Gratuit (quête)';
  } else {
    costPart = `${ticketsRequired} ${ticketWord} (${formatTowerNumber(combatTickets)} ${dispoWord})`;
  }

  let subLabel = '';
  if (lvlOffset > 0) {
    subLabel = isEn
      ? `Wagon ${currentWagon} (+${statPct}% stats) · ${costPart} · ${rewardPart}`
      : `Wagon ${currentWagon} (+${statPct} % stats) · ${costPart} · ${rewardPart}`;
  } else {
    subLabel = `Wagon 1 · ${costPart} · ${rewardPart}`;
  }

  const shortfallLabel = isShort
    ? (isEn ? 'Missing 1 ticket' : 'Il manque 1 ticket')
    : null;

  return {
    mainLabel,
    subLabel,
    shortfallLabel,
    fillRatio,
    state,
  };
}

function buildChampionsStartLabelHtml(game: GameRuntime): string {
  const ticketsRequired = getCombatEntryTicketCost();
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  return `${towerT(game, 'champions.startLabel', 'Lancer la Tour des Champions')} - ${ticketsRequired} ${ticketImg}`;
}

function isChampionsStartDisabled(game: GameRuntime): boolean {
  return canStartChampionsTowerRun(game) != null;
}

interface TowerStartData {
  mainLabel: string;
  subLabel: string;
  shortfallLabel: string | null;
  fillRatio: number;
  state: 'buyable' | 'short';
  legacyHtml: string;
}

function computeTowerStartData(game: GameRuntime): TowerStartData {
  const batchSize = clampTowerBatchSize(game);
  const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
  const combatTickets = Math.max(0, Math.floor(Number(game.combatTickets) || 0));
  const startFloor = Math.max(1, Math.floor(Number(game.towerAscentStartFloor) || 1));
  const isFree = ticketsRequired === 0;
  const isShort = !isFree && combatTickets < ticketsRequired;
  const state: 'buyable' | 'short' = isShort ? 'short' : 'buyable';
  const fillRatio = ticketsRequired > 0 ? Math.min(1, Math.max(0, combatTickets / ticketsRequired)) : 1;
  const missing = Math.max(0, ticketsRequired - combatTickets);

  const mainLabel = towerT(game, 'tower.startLabel', "Lancer l'ascension");
  const runsWord = batchSize > 1
    ? towerT(game, 'tower.batch.runsShort', 'runs')
    : towerT(game, 'tower.batch.runSingular', 'run');
  const ticketWord = ticketsRequired === 1
    ? towerT(game, 'tower.startTicketSingular', 'ticket')
    : towerT(game, 'tower.startTicketPlural', 'tickets');

  let subLabel = '';
  if (isFree) {
    subLabel = towerT(
      game,
      'tower.startSubFree',
      "{runs} {runsWord} · départ étage {floor} · Gratuit (quête)",
      { runs: batchSize, runsWord, floor: startFloor }
    );
  } else {
    subLabel = `${batchSize} ${runsWord} · départ étage ${startFloor} · ${ticketsRequired} ${ticketWord} (${formatTowerNumber(combatTickets)} dispo)`;
  }

  const shortfallLabel = isShort
    ? towerT(game, 'tower.startShortfall', 'Il manque {missing} {ticketWord}', {
        missing: formatTowerNumber(missing),
        ticketWord,
      })
    : null;

  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  let legacyHtml = '';
  if (batchSize > 1) {
    const perRunHint = towerT(game, 'tower.batch.perRunTicketHint', 'requis (1/run)');
    legacyHtml = `${mainLabel} - ${ticketsRequired} ${ticketImg} ${ticketWord} ${perRunHint} (${batchSize} ${runsWord})`;
  } else if (isFree) {
    legacyHtml = `${mainLabel} - ${towerT(game, 'tower.startFreeQuest', 'gratuit (quete)')}`;
  } else {
    legacyHtml = `${mainLabel} - ${ticketsRequired} ${ticketImg} ${towerT(game, 'tower.startRequirement', 'requis')}`;
  }

  return {
    mainLabel,
    subLabel,
    shortfallLabel,
    fillRatio,
    state,
    legacyHtml,
  };
}

function quickClearBusy(game: GameRuntime): boolean {
  if (game.towerState?.isActive) return true;
  if (game.subwayState?.isActive) return true;
  if (game.championsTowerState?.isActive) return true;
  if (game.arenaState?.active) return true;
  return false;
}

function escapeTooltipHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function computeTowerQuickClearData(game: GameRuntime, language: string): {
  visible: boolean;
  disabled: boolean;
  mainLabel: string;
  subLabel: string;
  shortfallLabel: string | null;
  tooltipTitle: string;
  tooltipBody: string;
} {
  const clearFloor = towerQuickClearStopFloor(game.towerRecord ?? 0);
  const runs = clampTowerBatchSize(game);
  const en = language === 'en';
  const mainLabel = towerT(game, 'tower.quickClearLabel', 'Quick Clear');
  const combat = Math.max(0, Math.floor(Number(game.combatTickets) || 0));
  const quick = Math.max(0, Math.floor(Number(game.towerQuickClearTickets) || 0));
  const subLabel = runs > 1
    ? towerT(
      game,
      'tower.quickClearSubPlural',
      en
        ? 'Up to floor {floor} · {runs} tickets + {runs} quick clear ({quick} left)'
        : 'Jusqu\'à l\'étage {floor} · {runs} tickets + {runs} quick clear ({quick} restants)',
      { floor: clearFloor, runs, quick },
    )
    : towerT(
      game,
      'tower.quickClearSub',
      en
        ? 'Up to floor {floor} · 1 ticket + 1 quick clear ({quick} left)'
        : 'Jusqu\'à l\'étage {floor} · 1 ticket + 1 quick clear ({quick} restants)',
      { floor: clearFloor, quick },
    );
  let shortfallLabel: string | null = null;
  if (combat < runs && quick < runs) {
    shortfallLabel = towerT(
      game,
      runs > 1 ? 'tower.quickClearShortBothPlural' : 'tower.quickClearShortBoth',
      en
        ? (runs > 1 ? 'Need {need} Battle Tickets and {need} Quick Clear tickets' : 'Need a Battle Ticket and a Quick Clear ticket')
        : (runs > 1 ? 'Il faut {need} tickets de combat et {need} tickets Quick Clear' : 'Il faut un ticket de combat et un ticket Quick Clear'),
      { need: runs },
    );
  } else if (combat < runs) {
    shortfallLabel = towerT(
      game,
      runs > 1 ? 'tower.quickClearShortCombatPlural' : 'tower.quickClearShortCombat',
      en
        ? (runs > 1 ? 'Need {need} Battle Tickets' : 'Need a Battle Ticket')
        : (runs > 1 ? 'Il faut {need} tickets de combat' : 'Il faut un ticket de combat'),
      { need: runs },
    );
  } else if (quick < runs) {
    shortfallLabel = towerT(
      game,
      runs > 1 ? 'tower.quickClearShortQcPlural' : 'tower.quickClearShortQc',
      en
        ? (runs > 1 ? 'Need {need} Quick Clear tickets' : 'Need a Quick Clear ticket')
        : (runs > 1 ? 'Il faut {need} tickets Quick Clear' : 'Il faut un ticket Quick Clear'),
      { need: runs },
    );
  }
  const busy = quickClearBusy(game);
  const floorPct = Math.round(QUICK_CLEAR_PAYOUT_RATE * 100);
  const cutPct = 100 - floorPct;
  const tooltipTitle = towerT(game, 'tower.quickClearTooltipTitle', 'Quick Clear');
  const tooltipCost = runs > 1
    ? towerT(
      game,
      'tower.quickClearTooltipCostPlural',
      en
        ? '{runs} Battle Tickets + {runs} Quick Clear tickets.'
        : '{runs} tickets de combat + {runs} tickets Quick Clear.',
      { runs },
    )
    : towerT(
      game,
      'tower.quickClearTooltipCost',
      en
        ? '1 Battle Ticket + 1 Quick Clear ticket.'
        : '1 ticket de combat + 1 ticket Quick Clear.',
    );
  const tooltipBody = [
    tooltipCost,
    towerT(
      game,
      'tower.quickClearTooltipRates',
      en
        ? 'The max floor is {floorPct}% of your record. Gains are reduced by {cutPct}%.'
        : 'L\'étage maximum représente {floorPct}% du record. Les gains sont amputés de {cutPct}%.',
      { floorPct, cutPct },
    ),
    towerT(
      game,
      'tower.quickClearTooltipShop',
      en
        ? 'Quick Clear tickets are sold at the Battle Subway shop.'
        : 'Les tickets Quick Clear sont en vente à la boutique Battle Subway.',
    ),
  ].map(escapeTooltipHtml).join('<br>');
  return {
    visible: clearFloor >= 1 && !!game.unlockedFeatures?.subwayTab,
    disabled: busy || combat < runs,
    mainLabel,
    subLabel,
    shortfallLabel,
    tooltipTitle: escapeTooltipHtml(tooltipTitle),
    tooltipBody,
  };
}

interface TowerQuestInfo {
  objective: string;
  target: number;
  remaining: number;
}

function getTowerQuestInfo(game: GameRuntime): TowerQuestInfo | null {
  const quest = (game.quests || []).find(
    (q) => (String(q.id) === 'story_tower_gen7_807' || String(q.id).includes('tower')) && q.accepted && !q.completed && q.target
  );
  if (!quest) return null;
  const target = Math.max(1, Math.floor(Number(quest.target) || 0));
  const record = Math.max(0, Math.floor(Number(game.towerRecord) || 0));
  const remaining = Math.max(0, target - record);
  const isEn =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language) === 'en'
      : false;
  const defaultText = isEn
    ? remaining === 0
      ? 'Quest objective: Floor {target} · Goal reached!'
      : remaining === 1
        ? 'Quest objective: Floor {target} · 1 floor left'
        : 'Quest objective: Floor {target} · {rem} floors left'
    : remaining === 0
      ? 'Objectif quête : Étage {target} · Objectif atteint !'
      : remaining === 1
        ? 'Objectif quête : Étage {target} · reste 1 étage'
        : 'Objectif quête : Étage {target} · reste {rem} étages';
  const objective = towerT(
    game,
    'tower.questObjective',
    defaultText,
    { target, rem: remaining }
  );
  return { objective, target, remaining };
}

export function buildTowerSnapshot(game: GameRuntime): TowerSnapshot {
  const relic = buildTowerRelicAutoPanelHtml(game);
  const ascent = buildTowerAscentMemoryPanelHtml(game);
  const batch = buildTowerBatchPanelHtml(game);
  const progressRows = getSubwaySetProgressRows(game);
  const todayRow = progressRows.find((r) => r.isToday) ?? progressRows[0];
  const startData = computeTowerStartData(game);
  const questInfo = getTowerQuestInfo(game);
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  const quickClear = computeTowerQuickClearData(game, language);
  const todayWagon = Number(
    todayRow ? getSubwayCurrentWagonIndex(game, todayRow.setId) : getSubwayCurrentWagonIndex(game),
  ) || 1;
  const subwayStartData = computeSubwayStartData(game, todayWagon, language);
  const weeklyResetLabel = formatSubwayWeeklyResetCountdown(Date.now(), language === 'en' ? 'en' : 'fr');
  const rawRecent = getTowerRecentRuns(game);
  const towerRecentRuns = (rawRecent || []).map((r) => ({
    floor: r.floor,
    marks: r.marks,
    durationFormatted: formatTowerRunDuration(r.durationMs),
    isRecord: r.isRecord,
  }));
  const towerRecentRunsSig = towerRecentRuns
    .map((r) => `${r.floor}:${r.marks}:${r.durationFormatted}:${r.isRecord ? 1 : 0}`)
    .join(';');
  return {
    language,
    titleLabel: towerT(game, 'tower.title', 'Tour de Combat'),
    recordLabel: towerT(game, 'tower.recordLabel', 'Record Personnel : Étage'),
    ticketsLabel: towerT(game, 'tower.ticketsLabel', 'Tickets de Combat :'),
    marksLabel: towerT(game, 'tower.marksLabel', 'Marques du Triomphe :'),
    startLabelHtml: startData.legacyHtml,
    startMainLabel: startData.mainLabel,
    startSubLabel: startData.subLabel,
    startShortfallLabel: startData.shortfallLabel,
    startFillRatio: startData.fillRatio,
    startState: startData.state,
    towerQuestObjective: questInfo ? questInfo.objective : null,
    towerQuestTarget: questInfo ? questInfo.target : null,
    towerQuestRemaining: questInfo ? questInfo.remaining : null,
    towerRecord: formatTowerNumber(game.towerRecord ?? 0),
    combatTickets: formatTowerNumber(game.combatTickets ?? 0),
    triumphMarks: formatTowerNumber(game.triumphMarks ?? 0),
    startDisabled: isTowerStartDisabled(game),
    quickClearVisible: quickClear.visible,
    quickClearDisabled: quickClear.disabled,
    quickClearMainLabel: quickClear.mainLabel,
    quickClearSubLabel: quickClear.subLabel,
    quickClearShortfallLabel: quickClear.shortfallLabel,
    quickClearTooltipTitle: quickClear.tooltipTitle,
    quickClearTooltipBody: quickClear.tooltipBody,
    batchVisible: batch.visible,
    batchHtml: batch.html,
    batchSig: batch.sig,
    maxBatchRuns: String(getTowerMaxBatchRuns(game)),
    towerBatchSize: String(clampTowerBatchSize(game)),
    relicAutoVisible: relic.visible,
    relicAutoHtml: relic.html,
    relicAutoSig: relic.sig,
    ascentMemoryVisible: ascent.visible,
    ascentMemoryHtml: ascent.html,
    ascentMemorySig: ascent.sig,
    subwayTabVisible: !!(game.unlockedFeatures && game.unlockedFeatures.subwayTab),
    subwayTitleLabel: towerT(game, 'subway.title', 'Battle Subway'),
    subwayRecordLabel: towerT(game, 'subway.recordLabel', 'Meilleure série :'),
    subwayBestStreak: String(game.subwayBestStreak ?? 0),
    subwayBpLabel: towerT(game, 'subway.bpLabel', 'Points Subway :'),
    subwayBP: String(game.subwayBP ?? 0),
    subwaySetProgressTitle: towerT(game, 'subway.setProgressTitle', 'Progression par set'),
    subwayTodaySetProgressLabel: towerT(
      game,
      'subway.todaySetProgress',
      'Set du jour — {label}',
      { label: todayRow?.label ?? '' },
    ),
    subwayTodayBestStreak: String(todayRow?.bestStreak ?? 0),
    subwayTodayWagonsCleared: String(todayRow?.wagonsCleared ?? 0),
    subwayTodayCurrentWagon: String(
      todayRow ? getSubwayCurrentWagonIndex(game, todayRow.setId) : getSubwayCurrentWagonIndex(game),
    ),
    subwaySetProgressWeeklyTemplate: towerTemplate(game, 'subway.setProgressWeekly', 'Progression hebdo : {n}'),
    subwaySetProgressPersonalBestTemplate: towerTemplate(game, 'subway.setProgressPersonalBest', 'Meilleur wagon : {n}'),
    subwaySetProgressCurrentWagonTemplate: towerTemplate(
      game,
      'subway.setProgressCurrentWagon',
      'Wagon : {n}',
    ),
    subwaySetProgressRows: progressRows.map((row) => ({
      setId: row.setId,
      dayIndex: row.dayIndex,
      label: row.label,
      themeType: row.themeType,
      bestStreak: String(row.bestStreak),
      wagonsCleared: String(row.wagonsCleared),
      currentWagon: String(getSubwayCurrentWagonIndex(game, row.setId)),
      isToday: row.isToday,
    })),
    subwaySetProgressSig: progressRows
      .map((r) => `${r.setId}:${r.bestStreak}:${r.wagonsCleared}:${getSubwayCurrentWagonIndex(game, r.setId)}:${r.isToday ? 1 : 0}`)
      .join('|'),
    subwayStartLabelHtml: buildSubwayStartLabelHtml(game),
    subwayStartDisabled: isSubwayStartDisabled(game),
    subwayActive: !!(game.subwayState && game.subwayState.isActive),
    subwayRunProgress: game.subwayState?.isActive
      ? `${game.subwayState.winsThisRun}/7`
      : '',
    subwayRunProgressLabel: towerT(game, 'subway.runProgressLabel', 'Série en cours'),
    subwayDescription: towerT(
      game,
      'subway.description',
      '7 combats dresseur par wagon. Stats brutes — pas de résonance régionale. Chaque wagon coûte 1 Ticket de Combat (partagé avec la Tour). Les Points Subway servent à la boutique.',
    ),
    subwayWagonProgressHint: towerT(
      game,
      'subway.wagonProgressHint',
      'Chaque wagon est plus difficile (+2 niveaux, +6 % stats). La progression des wagons repart à zéro chaque semaine. Un wagon complet (7/7) rapporte 1 Point Subway.',
    ),
    subwayWagonLabel: towerT(game, 'subway.wagonLabel', 'Wagon actuel'),
    subwayCurrentWagon: String(getSubwayCurrentWagonIndex(game)),
    subwayTodayThemeType: todayRow?.themeType ?? 'normal',
    subwayWeeklyResetLabel: weeklyResetLabel,
    subwayStartMainLabel: subwayStartData.mainLabel,
    subwayStartSubLabel: subwayStartData.subLabel,
    subwayStartShortfallLabel: subwayStartData.shortfallLabel,
    subwayStartFillRatio: subwayStartData.fillRatio,
    subwayStartState: subwayStartData.state,
    subwayActiveTrainerIndex: game.subwayState?.isActive ? Math.max(1, Number(game.subwayState.currentBattle) || 1) : 0,
    subwayWinsThisRun: game.subwayState?.isActive ? Math.max(0, Number(game.subwayState.winsThisRun) || 0) : 0,
    championsTabVisible: !!(game.unlockedFeatures && game.unlockedFeatures.championsTowerTab),
    championsTitleLabel: towerT(game, 'champions.title', 'Tour des Champions'),
    championsBestCycleLabel: towerT(game, 'champions.bestCycle', 'Meilleur cycle :'),
    championsBestCycle: String(game.championsTowerBestCycle ?? 0),
    championsTotalCycles: String(game.championsTowerTotalCycles ?? 0),
    championsStartLabelHtml: buildChampionsStartLabelHtml(game),
    championsStartDisabled: isChampionsStartDisabled(game),
    championsActive: !!(game.championsTowerState && game.championsTowerState.isActive),
    championsProgressLabel: getChampionsTowerProgressLabel(game),
    championsDescription: towerT(
      game,
      'champions.description',
      'Enchaînez les 9 ligues Pokémon. Pas de soin entre dresseurs d\'une même ligue ; soin complet entre chaque ligue. Après Paldea, cycle 2 avec difficulté accrue.',
    ),
    towerRecentRuns,
    towerRecentRunsSig,
  };
}

let lastTowerSnapshot: TowerSnapshot | null = null;

/** @internal Vitest only */
export function resetTowerSnapshotDedupForTests(): void {
  lastTowerSnapshot = null;
}

export function notifyTowerChanged(game: GameRuntime): void {
  const tower = buildTowerSnapshot(game);
  if (lastTowerSnapshot && !towerSnapshotWouldChange(lastTowerSnapshot, tower)) return;
  lastTowerSnapshot = tower;
  publish({ type: Evt.TOWER_CHANGED, tower });
}
