import { BALANCE } from '../../constants/balance/balance.js';
import { RARITY } from '../../constants/core.ts';

/** Clamp stored tower boss loot bonus (0 = no bonus, 1.5 = ×2.5 multiplier). */
export function getTowerBossLootBonus(raw: unknown): number {
    return Math.min(1.5, Math.max(0, Number(raw) || 0));
}

/** Multiplicative drop chance: base × (1 + bonus), capped at 100%. */
export function effectiveDropChance(base: number, bonus: number): number {
    const b = getTowerBossLootBonus(bonus);
    return Math.min(1, base * (1 + b));
}

const BOSS_EGG_LEGENDARY_CAP = 0.05;
const BOSS_EGG_EPIC_CAP = 0.80;

/** Roll boss egg rarity with multiplicative threshold boost from tower boss loot upgrade. */
export function rollBossEggRarityWithBonus(bonus: number): string {
    const mult = 1 + getTowerBossLootBonus(bonus);
    const bal = BALANCE;
    const legendary = Math.min(BOSS_EGG_LEGENDARY_CAP, bal.BOSS_EGG_ROLL_LEGENDARY * mult);
    const epic = Math.min(BOSS_EGG_EPIC_CAP, Math.max(legendary, bal.BOSS_EGG_ROLL_EPIC * mult));
    const r = Math.random();
    if (r < legendary) return RARITY.LEGENDARY;
    if (r < epic) return RARITY.EPIC;
    return RARITY.RARE;
}
