/**
 * Quick Clear: replay tower reward rolls up to floor(record × 0.9), then pay 90%.
 * Combat is not simulated. Relic picks use the auto-picker on a shadow buff state.
 */

import { BALANCE } from '../../constants/balance/balance.ts';
import { getSubwayShopItemCost, SUBWAY_SHOP_ITEMS } from '../../constants/balance/subwayRewards.ts';
import { TOWER_RELICS } from '../../constants/balance/towerRelics.ts';
import { game as runtimeGame, setGameInstance } from '../../gameManager.ts';
import type { GameRuntime } from '../types/game.js';
import type { TowerState } from '../types/combat.ts';
import { getTowerVictoryExpLevelMult } from './towerCombatXp.ts';
import { effectiveDropChance, getTowerBossLootBonus, rollBossEggRarityWithBonus } from './towerBossLootBonus.ts';
import { clampTowerBatchSize } from './towerBatchRuns.ts';
import { logMessage } from '../ui/modals.ts';
import {
    buildTowerItemChoiceEntry,
    getTowerRelicPicksPerBoss,
    isTowerRelicCappedLogic,
    pickTowerRelicAutoIndex,
    rollTowerRelicChoices,
    showTowerCompletionModalLogic,
    towerText,
} from '../../towerSystem.ts';

export const QUICK_CLEAR_PAYOUT_RATE = 0.9;

const RELIC_CATALOG = TOWER_RELICS as unknown as Record<string, {
    values?: Record<string, unknown>;
    effect?: (game: GameRuntime, val: number) => void;
}>;

export interface QuickClearLedger {
    clearFloor: number;
    marks: number;
    teamXp: number;
    pensionXp: number;
    eggs: Record<string, number>;
    items: Record<string, number>;
}

export function towerQuickClearStopFloor(record: number): number {
    const n = Math.floor(Number(record) || 0);
    if (n <= 0) return 0;
    return Math.floor(n * QUICK_CLEAR_PAYOUT_RATE);
}

export function quickClearFloorMarks(
    floor: number,
    triumphFlat: number,
    bossBonus: number,
    isBoss: boolean,
    scale: (amount: number) => number,
    roll: () => number,
): number {
    let marks = 1 + Math.floor(floor / 100);
    if (roll() < ((floor % 100) / 100)) marks += 1;
    const prime = Math.min(3, Math.max(0, Math.floor(Number(triumphFlat) || 0)));
    if (prime > 0) marks += prime;
    if (isBoss && bossBonus > 0) marks += bossBonus;
    const scaled = scale(marks);
    return Math.max(0, Math.floor(Number(scaled) || 0));
}

function emptyLedger(clearFloor: number): QuickClearLedger {
    return {
        clearFloor,
        marks: 0,
        teamXp: 0,
        pensionXp: 0,
        eggs: {},
        items: {},
    };
}

function addCount(bag: Record<string, number>, key: string, amount: number): void {
    const qty = Math.max(0, Math.floor(Number(amount) || 0));
    if (!key || qty <= 0) return;
    bag[key] = (bag[key] || 0) + qty;
}

function keepCount(count: number, rate: number, roll: () => number): number {
    const n = Math.max(0, Math.floor(count) || 0);
    let kept = 0;
    for (let i = 0; i < n; i++) {
        if (roll() < rate) kept += 1;
    }
    return kept;
}

/** Marks and XP are floored. Each egg and item is kept independently so a stack of 1 is not erased. */
export function applyQuickClearPayoutMalus(
    raw: QuickClearLedger,
    roll: () => number = Math.random,
): QuickClearLedger {
    const rate = QUICK_CLEAR_PAYOUT_RATE;
    const eggs: Record<string, number> = {};
    const items: Record<string, number> = {};
    for (const [rarity, count] of Object.entries(raw.eggs)) {
        const kept = keepCount(count, rate, roll);
        if (kept > 0) eggs[rarity] = kept;
    }
    for (const [key, count] of Object.entries(raw.items)) {
        const kept = keepCount(count, rate, roll);
        if (kept > 0) items[key] = kept;
    }
    return {
        clearFloor: raw.clearFloor,
        marks: Math.floor(Math.max(0, raw.marks) * rate),
        teamXp: Math.floor(Math.max(0, raw.teamXp) * rate),
        pensionXp: Math.floor(Math.max(0, raw.pensionXp) * rate),
        eggs,
        items,
    };
}

function bossInterval(): number {
    return Math.max(1, Math.floor(Number(BALANCE.TOWER_ENEMY.BOSS_FLOOR_INTERVAL) || 10));
}

function scaleMarks(game: GameRuntime, amount: number): number {
    if (typeof game.scaleMasteryTriumphMarksAmount === 'function') {
        return game.scaleMasteryTriumphMarksAmount(amount);
    }
    return amount;
}

function applyDraftedRelic(game: GameRuntime, choice: {
    isItem?: boolean;
    itemKey?: string;
    amount?: number;
    key?: string;
    rarity?: string;
}, items: Record<string, number>): void {
    if (choice.isItem && choice.itemKey) {
        addCount(items, choice.itemKey, choice.amount ?? 1);
        return;
    }
    const key = choice.key;
    if (!key) return;
    const relic = RELIC_CATALOG[key];
    if (!relic || typeof relic.effect !== 'function') return;
    const raw = relic.values?.[choice.rarity || ''];
    const numeric = Number(raw) || 0;
    const team = game.playerTeam;
    game.playerTeam = [];
    try {
        relic.effect(game, numeric);
    } finally {
        game.playerTeam = team;
    }
}

function draftBossRelics(game: GameRuntime, items: Record<string, number>): void {
    const picks = getTowerRelicPicksPerBoss(game);
    const itemDropChance = Math.max(0, Math.min(1,
        Number(game.permanentBoosts?.tower_item_drop_chance) || 0,
    ));
    for (let pick = 0; pick < picks; pick++) {
        const available = Object.keys(RELIC_CATALOG).filter((key) => {
            const relic = RELIC_CATALOG[key];
            return !!relic && !isTowerRelicCappedLogic(game, key, relic);
        });
        if (available.length === 0) return;
        const choices = rollTowerRelicChoices(game, available);
        if (itemDropChance > 0) {
            for (let idx = 0; idx < choices.length; idx++) {
                if (Math.random() < itemDropChance) {
                    const itemChoice = buildTowerItemChoiceEntry();
                    if (itemChoice) choices[idx] = itemChoice as typeof choices[number];
                }
            }
        }
        if (!choices.length) return;
        const pickIdx = pickTowerRelicAutoIndex(game, choices);
        if (pickIdx < 0) return;
        const choice = choices[pickIdx];
        if (!choice) return;
        applyDraftedRelic(game, choice, items);
    }
}

function rollBossLoot(game: GameRuntime, lootBonus: number, eggs: Record<string, number>): void {
    // Drop helpers call addItem, which the sim redirects into the ledger.
    game.rollItemDrop?.(true, {
        excludeHeldItemsAtRarities: ['legendary'],
        lootMultBonus: lootBonus,
    });
    game.tryDropTimeDust?.('Boss Tour', lootBonus);
    game.tryDropHeldItem?.('Boss Tour', lootBonus);
    game.tryDropTradeStone?.('Boss Tour', lootBonus);
    game.tryDropPrestigeStone?.('Boss Tour', effectiveDropChance(0.05, lootBonus));
    game.tryDropTmEraser?.('Boss Tour', effectiveDropChance(0.02, lootBonus));

    const rarity = rollBossEggRarityWithBonus(lootBonus);
    addCount(eggs, rarity, 1);
}

export function simulateTowerQuickClear(game: GameRuntime): QuickClearLedger {
    const clearFloor = towerQuickClearStopFloor(game.towerRecord ?? 0);
    const ledger = emptyLedger(clearFloor);
    if (clearFloor < 1) return ledger;

    const interval = bossInterval();
    const bossBonus = Math.min(5, Math.max(0, Math.floor(Number(game.permanentBoosts?.boss_mark_bonus) || 0)));
    const lootBonus = getTowerBossLootBonus(game.permanentBoosts?.tower_boss_loot_bonus);
    const towerMult = getTowerVictoryExpLevelMult(
        BALANCE.TOWER_VICTORY_EXP_LEVEL_MULT,
        game.permanentBoosts,
    );
    const expMult = typeof game.getExpMultiplier === 'function' ? (Number(game.getExpMultiplier()) || 0) : 1;
    const pensionOn = !!game.unlockedFeatures?.towerPensionXp;
    const pensionRate = BALANCE.PENSION_EXP_RATIO + (Number(game.permanentBoosts?.pensionXp) || 0);

    const savedTower = game.towerState;
    const savedAddItem = game.addItem.bind(game);
    const prevSuppress = game.suppressLogs;
    const prevOffline = game.isOfflineSimulating;
    const previousRuntime = runtimeGame;

    const shadow: TowerState = {
        isActive: false,
        currentFloor: 0,
        currentEnemyIndex: 0,
        enemyTeam: [],
        buffs: {},
    };

    game.suppressLogs = true;
    game.isOfflineSimulating = true;
    setGameInstance(game);
    game.towerState = shadow;
    game.addItem = (itemKey: string, quantity = 1) => {
        addCount(ledger.items, itemKey, quantity);
    };

    try {
        for (let floor = 1; floor <= clearFloor; floor++) {
            const expGain = Math.floor(floor * towerMult * expMult);
            if (expGain > 0) ledger.teamXp += expGain;
            if (pensionOn && expGain > 0) {
                const pensionExp = Math.floor(expGain * pensionRate);
                if (pensionExp > 0) ledger.pensionXp += pensionExp;
            }

            const triumphFlat = Number(shadow.buffs?.triumph_marks_flat) || 0;
            const isBoss = floor % interval === 0;
            ledger.marks += quickClearFloorMarks(
                floor,
                triumphFlat,
                bossBonus,
                isBoss,
                (amount) => scaleMarks(game, amount),
                Math.random,
            );

            if (isBoss) {
                rollBossLoot(game, lootBonus, ledger.eggs);
                draftBossRelics(game, ledger.items);
            }
        }
    } finally {
        game.towerState = savedTower;
        game.addItem = savedAddItem;
        game.suppressLogs = prevSuppress;
        game.isOfflineSimulating = prevOffline;
        setGameInstance(previousRuntime);
    }

    return ledger;
}

const QUICK_CLEAR_TICKET_OFFER_ID = 'subway_quick_clear_ticket';

function addLedger(total: QuickClearLedger, part: QuickClearLedger): void {
    total.marks += part.marks;
    total.teamXp += part.teamXp;
    total.pensionXp += part.pensionXp;
    for (const [rarity, count] of Object.entries(part.eggs)) {
        if (count > 0) total.eggs[rarity] = (total.eggs[rarity] || 0) + count;
    }
    for (const [key, count] of Object.entries(part.items)) {
        if (count > 0) total.items[key] = (total.items[key] || 0) + count;
    }
}

function quickClearTicketOffer(): { amount: number; cost: number } {
    const offer = SUBWAY_SHOP_ITEMS.find((item) => item.id === QUICK_CLEAR_TICKET_OFFER_ID);
    if (!offer) return { amount: 3, cost: 1 };
    return { amount: offer.amount, cost: getSubwayShopItemCost(offer) };
}

function grantLedger(game: GameRuntime, paid: QuickClearLedger): void {
    if (paid.marks > 0) {
        game.triumphMarks = (Number(game.triumphMarks) || 0) + paid.marks;
        if (game.stats) {
            game.stats.totalTriumphMarksEarned = (game.stats.totalTriumphMarksEarned || 0) + paid.marks;
        }
    }
    if (!game.eggs) {
        game.eggs = { common: 0, rare: 0, epic: 0, legendary: 0 };
    }
    for (const [rarity, count] of Object.entries(paid.eggs)) {
        if (count > 0) game.eggs[rarity] = (game.eggs[rarity] || 0) + count;
    }
    for (const [key, count] of Object.entries(paid.items)) {
        if (count > 0) game.addItem?.(key, count, false);
    }
    if (paid.teamXp > 0) {
        for (const creature of game.playerTeam || []) {
            creature?.gainExp?.(paid.teamXp);
        }
    }
    if (paid.pensionXp > 0) {
        for (const creature of game.pension || []) {
            creature?.gainExp?.(paid.pensionXp);
        }
    }
}

function quickClearBusy(game: GameRuntime): boolean {
    if (game.towerState?.isActive) return true;
    if (game.subwayState?.isActive) return true;
    if (game.championsTowerState?.isActive) return true;
    if (game.arenaState?.active) return true;
    return false;
}

const QUICK_CLEAR_CONFIRM_MODAL_ID = 'confirmQuickClearModal';

export function closeQuickClearConfirmModal(): void {
    if (typeof document === 'undefined') return;
    document.getElementById(QUICK_CLEAR_CONFIRM_MODAL_ID)?.remove();
}

function appendHighlighted(
    parent: HTMLElement,
    template: string,
    vars: Record<string, { value: string; highlight: boolean }>,
): void {
    const re = /\{(\w+)\}/g;
    let last = 0;
    let match: RegExpExecArray | null;
    while ((match = re.exec(template)) !== null) {
        if (match.index > last) parent.append(document.createTextNode(template.slice(last, match.index)));
        const spec = vars[match[1] ?? ''];
        const value = spec?.value ?? '';
        if (spec?.highlight) {
            const span = document.createElement('span');
            span.className = 'confirm-quick-clear-cost';
            span.textContent = value;
            parent.append(span);
        } else {
            parent.append(document.createTextNode(value));
        }
        last = match.index + match[0].length;
    }
    if (last < template.length) parent.append(document.createTextNode(template.slice(last)));
}

export function openQuickClearConfirmModal(game: GameRuntime): void {
    if (typeof document === 'undefined') return;
    closeQuickClearConfirmModal();

    const runs = clampTowerBatchSize(game);
    const clearFloor = towerQuickClearStopFloor(game.towerRecord ?? 0);
    const combat = Math.floor(Number(game.combatTickets) || 0);
    const quick = Math.floor(Number(game.towerQuickClearTickets) || 0);
    const highlight = runs > 1;
    const runLabel = { value: String(runs), highlight };
    const floorLabel = { value: String(clearFloor), highlight: false };

    const overlay = document.createElement('div');
    overlay.id = QUICK_CLEAR_CONFIRM_MODAL_ID;
    overlay.className = 'stats-modal show';
    overlay.addEventListener('click', (event) => {
        if (event.target === overlay) closeQuickClearConfirmModal();
    });

    const box = document.createElement('div');
    box.className = 'stats-content confirm-pension-storage-content';

    const header = document.createElement('div');
    header.className = 'stats-header';
    const title = document.createElement('h2');
    title.textContent = towerText(game, 'tower.quickClearConfirmTitle', 'Quick Clear', 'Quick Clear');
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'stats-close';
    closeBtn.dataset.action = 'closeQuickClearConfirm';
    closeBtn.textContent = '\u2715';
    header.append(title, closeBtn);

    const text = document.createElement('div');
    text.className = 'confirm-pension-storage-text';
    const launch = document.createElement('p');
    appendHighlighted(
        launch,
        towerText(
            game,
            'tower.quickClearConfirmLaunch',
            'Lancer {runs} Quick Clear jusqu\'à l\'étage {floor} ?',
            'Launch {runs} Quick Clear up to floor {floor}?',
            { runs: '{runs}', floor: '{floor}' },
        ),
        { runs: runLabel, floor: floorLabel },
    );
    const cost = document.createElement('p');
    const costKey = runs > 1 ? 'tower.quickClearConfirmCostPlural' : 'tower.quickClearConfirmCost';
    const costFallbackFr = runs > 1
        ? 'Coût : {runs} tickets de combat et {runs} tickets Quick Clear.'
        : 'Coût : {runs} ticket de combat et {runs} ticket Quick Clear.';
    const costFallbackEn = runs > 1
        ? 'Cost: {runs} Battle Tickets and {runs} Quick Clear tickets.'
        : 'Cost: {runs} Battle Ticket and {runs} Quick Clear ticket.';
    appendHighlighted(
        cost,
        towerText(game, costKey, costFallbackFr, costFallbackEn, { runs: '{runs}' }),
        { runs: runLabel },
    );
    text.append(launch, cost);

    const rates = document.createElement('p');
    rates.className = 'confirm-quick-clear-rates';
    const floorPct = Math.round(QUICK_CLEAR_PAYOUT_RATE * 100);
    rates.textContent = towerText(
        game,
        'tower.quickClearConfirmRates',
        'L\'étage maximum du Quick Clear représente {floorPct}% de votre record. Lors d\'un run Quick Clear, les gains sont amputés de {cutPct}% par rapport à un run classique.',
        'The Quick Clear max floor is {floorPct}% of your record. On a Quick Clear run, gains are reduced by {cutPct}% compared with a normal run.',
        { floorPct, cutPct: 100 - floorPct },
    );

    const parts: HTMLElement[] = [header, text, rates];
    if (quick < runs) {
        const offer = quickClearTicketOffer();
        const bp = Math.floor(Number(game.subwayBP) || 0);
        const shop = document.createElement('div');
        shop.className = 'confirm-quick-clear-shop';
        const note = document.createElement('p');
        note.textContent = towerText(
            game,
            'tower.quickClearShopShort',
            'Tickets Quick Clear : {have}/{need}.',
            'Quick Clear tickets: {have}/{need}.',
            { have: quick, need: runs },
        );
        const buy = document.createElement('button');
        buy.type = 'button';
        buy.className = 'btn confirm-quick-clear-shop-buy';
        buy.dataset.action = 'buyQuickClearTicketsFromConfirm';
        buy.textContent = towerText(
            game,
            'tower.quickClearShopBuy',
            'Acheter ×{amount} · {cost} BP',
            'Buy ×{amount} · {cost} BP',
            { amount: offer.amount, cost: offer.cost },
        );
        if (bp < offer.cost) buy.disabled = true;
        const balance = document.createElement('span');
        balance.className = 'confirm-quick-clear-shop-balance';
        balance.textContent = towerText(
            game,
            'tower.quickClearShopBalance',
            '{bp} BP',
            '{bp} BP',
            { bp },
        );
        shop.append(note, buy, balance);
        parts.push(shop);
    }

    const actions = document.createElement('div');
    actions.className = 'confirm-pension-storage-actions';
    const cancel = document.createElement('button');
    cancel.type = 'button';
    cancel.className = 'btn confirm-pension-storage-cancel';
    cancel.dataset.action = 'closeQuickClearConfirm';
    cancel.textContent = towerText(game, 'tower.quickClearCancel', 'Annuler', 'Cancel');
    const submit = document.createElement('button');
    submit.type = 'button';
    submit.className = 'btn confirm-pension-storage-submit';
    submit.dataset.action = 'executeQuickClearTower';
    submit.textContent = towerText(game, 'tower.quickClearConfirmAction', 'Confirmer', 'Confirm');
    submit.disabled = combat < runs || quick < runs;
    actions.append(cancel, submit);
    parts.push(actions);

    box.append(...parts);
    overlay.appendChild(box);
    document.body.appendChild(overlay);
}

export function quickClearTowerLogic(
    game: GameRuntime,
    confirm?: (message: string) => boolean,
): boolean {
    const clearFloor = towerQuickClearStopFloor(game.towerRecord ?? 0);
    if (clearFloor < 1) return false;
    if (quickClearBusy(game)) {
        logMessage(towerText(
            game,
            'tower.quickClearBusy',
            'Terminez d\'abord le combat en cours.',
            'Finish the current battle first.',
        ));
        return false;
    }

    const runs = clampTowerBatchSize(game);
    const combat = Math.floor(Number(game.combatTickets) || 0);
    const quick = Math.floor(Number(game.towerQuickClearTickets) || 0);
    if (!confirm) {
        openQuickClearConfirmModal(game);
        return false;
    }
    if (!confirm('')) return false;
    if (combat < runs || quick < runs) {
        logMessage(towerText(
            game,
            'tower.quickClearNeedTickets',
            'Il faut {need} tickets de combat et {need} tickets Quick Clear.',
            'You need {need} Battle Tickets and {need} Quick Clear tickets.',
            { need: runs },
        ));
        return false;
    }

    const recordBefore = game.towerRecord;
    const floorsBefore = game.stats?.towerFloorsClimbed;
    const paid = emptyLedger(clearFloor);
    for (let i = 0; i < runs; i++) {
        addLedger(paid, applyQuickClearPayoutMalus(simulateTowerQuickClear(game)));
        game.towerRecord = recordBefore;
        if (game.stats && floorsBefore !== undefined) {
            game.stats.towerFloorsClimbed = floorsBefore;
        }
    }

    game.combatTickets = combat - runs;
    game.towerQuickClearTickets = quick - runs;
    game.towerRecord = recordBefore;
    if (game.stats && floorsBefore !== undefined) {
        game.stats.towerFloorsClimbed = floorsBefore;
    }

    grantLedger(game, paid);

    const prevRunStats = game.towerState?.runStats;
    if (game.towerState) {
        game.towerState.runStats = {
            marksGained: paid.marks,
            floorsCleared: paid.clearFloor * runs,
            teamXpGained: paid.teamXp,
            pensionXpGained: paid.pensionXp,
            eggs: { ...paid.eggs },
            items: { ...paid.items },
            runDurationMs: 60_000 * runs,
        };
        showTowerCompletionModalLogic(game, paid.clearFloor, false, false);
        game.towerState.runStats = prevRunStats;
    }

    logMessage(towerText(
        game,
        'tower.quickClearDone',
        'Quick Clear ×{runs} jusqu\'à l\'étage {floor} : +{marks} marques.',
        'Quick Clear ×{runs} up to floor {floor}: +{marks} marks.',
        { runs, floor: paid.clearFloor, marks: paid.marks },
    ));

    game.updateDisplay?.(['tower', 'shop', 'items', 'team', 'eggs', 'pension']);
    game.updatePlayerStatsDisplay?.();
    game.saveGame?.();
    return true;
}
